266	// ServiceDecodedEvent is a typed view of one ServiceEvent. Exactly one payload
267	// pointer is non-nil for a known event type.
268	type ServiceDecodedEvent struct {
269		Type     string
270		Sequence int64
271		Time     time.Time
272		Metadata map[string]string
273	
274		TextDelta        *ServiceTextDeltaData
275		ToolCall         *ServiceToolCallData
276		ToolResult       *ServiceToolResultData
277		Compaction       *ServiceCompactionData
278		RoutingDecision  *ServiceRoutingDecisionData
279		Stall            *ServiceStallData
