285	func DecodeServiceEvent(ev ServiceEvent) (ServiceDecodedEvent, error) {
286		decoded := ServiceDecodedEvent{
287			Type:     string(ev.Type),
288			Sequence: ev.Sequence,
289			Time:     ev.Time,
290			Metadata: ev.Metadata,
291		}
292		switch string(ev.Type) {
293		case ServiceEventTypeTextDelta:
294			var payload ServiceTextDeltaData
295			if err := decodeServicePayload(ev, &payload); err != nil {
296				return decoded, err
297			}
298			decoded.TextDelta = &payload
299		case ServiceEventTypeToolCall:
300			var payload ServiceToolCallData
301			if err := decodeServicePayload(ev, &payload); err != nil {
302				return decoded, err
303			}
304			decoded.ToolCall = &payload
305		case ServiceEventTypeToolResult:
306			var payload ServiceToolResultData
307			if err := decodeServicePayload(ev, &payload); err != nil {
308				return decoded, err
309			}
310			decoded.ToolResult = &payload
311		case ServiceEventTypeCompaction:
312			var payload ServiceCompactionData
313			if err := decodeServicePayload(ev, &payload); err != nil {
314				return decoded, err
315			}
316			decoded.Compaction = &payload
317		case ServiceEventTypeRoutingDecision:
318			var payload ServiceRoutingDecisionData
319			if err := decodeServicePayload(ev, &payload); err != nil {
320				return decoded, err
321			}
322			decoded.RoutingDecision = &payload
323		case ServiceEventTypeStall:
324			var payload ServiceStallData
325			if err := decodeServicePayload(ev, &payload); err != nil {
326				return decoded, err
327			}
328			decoded.Stall = &payload
329		case ServiceEventTypeFinal:
330			var payload ServiceFinalData
331			if err := decodeServicePayload(ev, &payload); err != nil {
332				return decoded, err
333			}
334			decoded.Final = &payload
335		case ServiceEventTypeOverride:
336			var payload ServiceOverrideData
337			if err := decodeServicePayload(ev, &payload); err != nil {
338				return decoded, err
339			}
340			decoded.Override = &payload
341		case ServiceEventTypeRejectedOverride:
342			var payload ServiceOverrideData
343			if err := decodeServicePayload(ev, &payload); err != nil {
344				return decoded, err
345			}
346			decoded.RejectedOverride = &payload
347		default:
348			return decoded, fmt.Errorf("decode service event %q: unknown type", ev.Type)
349		}
350		return decoded, nil
351	}
