353	func decodeServicePayload(ev ServiceEvent, dst any) error {
354		if len(ev.Data) == 0 {
355			return fmt.Errorf("decode service event %q: empty data", ev.Type)
356		}
357		if err := json.Unmarshal(ev.Data, dst); err != nil {
358			return fmt.Errorf("decode service event %q: %w", ev.Type, err)
359		}

