177:// RoutingActual captures the resolved fallback chain on a final event.
178:type RoutingActual struct {

370		start := time.Now()
371		var seq atomic.Int64
372	
373		// Open the service-owned session log writer and guarantee a terminal
374		// session.end record plus a clean file close even on unexpected exits.
375		// CONTRACT-003 makes session-log lifecycle a service responsibility; the
376		// per-path finalizeAndEmit calls below feed writeEnd in lock-step with
377		// the public final event.
378		sl := s.openSessionLog(req, decision, sessionID)
379		if overrideCtx != nil {
380			// Stash sl so the fan-out goroutine in wrapExecuteWithHub can
381			// persist override events to the session log (ADR-006 §5).
382			overrideCtx.sl.Store(sl)
383		}
384		defer func() {
385			if !sl.endWritten() {
386				sl.writeEnd(req, meta, harnesses.FinalData{
387					Status:     "cancelled",
388					Error:      "session ended without final event",
389					DurationMS: time.Since(start).Milliseconds(),
390					RoutingActual: &harnesses.RoutingActual{
391						Harness:  decision.Harness,
392						Provider: decision.Provider,
393						Model:    decision.Model,
394					},
395				})
396			}
397			sl.close()
398		}()
399	
400		// Wall-clock cap.
401		runCtx := ctx
402		if req.Timeout > 0 {
403			var cancel context.CancelFunc
404			runCtx, cancel = context.WithTimeout(ctx, req.Timeout)
405			defer cancel()
406		}
407	
408		// Emit routing_decision start event. Include session_id so callers can
409		// extract it and pass to TailSessionLog.
410		emitJSON(out, &seq, harnesses.EventTypeRoutingDecision, meta, ServiceRoutingDecisionData{
411			Harness:    decision.Harness,
412			Provider:   decision.Provider,
413			Endpoint:   decision.Endpoint,
414			Model:      decision.Model,
415			Reason:     decision.Reason,
416			SessionID:  sessionID,
417			Candidates: routingDecisionEventCandidates(decision.Candidates),
418		})
419	
420		// Branch: native ("agent") path runs the in-process loop; subprocess
421		// paths instantiate the matching internal/harnesses/<name>.Runner.
422		switch decision.Harness {
423		case "agent", "":
424			s.runNative(runCtx, req, decision, meta, out, &seq, start, sl)
425		case "claude":
426			s.runSubprocess(runCtx, req, decision, meta, out, &seq, start, sl, &claudeharness.Runner{})
427		case "codex":
428			s.runSubprocess(runCtx, req, decision, meta, out, &seq, start, sl, &codexharness.Runner{})
429		case "gemini":
430			s.runSubprocess(runCtx, req, decision, meta, out, &seq, start, sl, &geminiharness.Runner{})
431		case "opencode":
432			s.runSubprocess(runCtx, req, decision, meta, out, &seq, start, sl, &opencodeharness.Runner{})
433		case "pi":
434			s.runSubprocess(runCtx, req, decision, meta, out, &seq, start, sl, &piharness.Runner{})
435		case "virtual":
436			s.runVirtual(runCtx, req, decision, meta, out, &seq, start, sl)
437		case "script":
438			s.runScript(runCtx, req, decision, meta, out, &seq, start, sl)
439		default:
440			if cfg, ok := s.registry.Get(decision.Harness); ok && cfg.IsHTTPProvider {
441				s.runNative(runCtx, req, decision, meta, out, &seq, start, sl)
442				return
443			}
444			// Unknown / unimplemented subprocess harnesses fail with an explicit
445			// final event so callers do not silently fall back.
446			finalizeAndEmit(out, &seq, meta, req, sl, harnesses.FinalData{
447				Status:     "failed",
448				Error:      fmt.Sprintf("harness %q dispatch not yet wired in service.Execute", decision.Harness),
449				DurationMS: time.Since(start).Milliseconds(),
450				RoutingActual: &harnesses.RoutingActual{
451					Harness:  decision.Harness,
452					Provider: decision.Provider,
453					Model:    decision.Model,
454				},
455			})
456		}
457	}
