460		inlineText := meta["virtual.response"]
461		cfg := virtualprovider.Config{
462			DictDir: meta["virtual.dict_dir"],
463		}
464		if inlineText != "" {
465			cfg.InlineResponses = []virtualprovider.InlineResponse{{
466				PromptMatch: metaValue(meta, "virtual.prompt_match", req.Prompt),
467				Response: agentcore.Response{
468					Content: inlineText,
469					Usage: agentcore.TokenUsage{
470						Input:  metadataInt(meta, "virtual.input_tokens"),
471						Output: metadataInt(meta, "virtual.output_tokens"),
472						Total:  metadataInt(meta, "virtual.total_tokens"),
473					},
474					Model: metaValue(meta, "virtual.model", decision.Model),
475				},
476				DelayMS: metadataInt(meta, "virtual.delay_ms"),
477			}}
478		}
479		if cfg.DictDir == "" && len(cfg.InlineResponses) == 0 {
480			finalizeAndEmit(out, seq, meta, req, sl, harnesses.FinalData{
481				Status:     "failed",
482				Error:      "virtual harness requires metadata virtual.response or virtual.dict_dir",
483				DurationMS: time.Since(start).Milliseconds(),
484				RoutingActual: &harnesses.RoutingActual{
485					Harness:  decision.Harness,
486					Provider: decision.Provider,
487					Model:    decision.Model,
488				},
489			})
490			return
491		}
492	
493		resp, err := virtualprovider.New(cfg).Chat(ctx, []agentcore.Message{{Role: agentcore.RoleUser, Content: req.Prompt}}, nil, agentcore.Options{})
