498				Provider: decision.Provider,
499				Model:    metaValue(meta, "virtual.model", decision.Model),
500			},
501		}
502		if err != nil {
503			final.Status = "failed"
504			final.Error = err.Error()
505			finalizeAndEmit(out, seq, meta, req, sl, final)
