525	func (s *service) runScript(ctx context.Context, req ServiceExecuteRequest, decision RouteDecision, meta map[string]string, out chan<- ServiceEvent, seq *atomic.Int64, start time.Time, sl *serviceSessionLog) {
526		delay := metadataInt(meta, "script.delay_ms")
527		if delay > 0 {
528			timer := time.NewTimer(time.Duration(delay) * time.Millisecond)
529			select {
530			case <-ctx.Done():
531				timer.Stop()
532				finalizeAndEmit(out, seq, meta, req, sl, harnesses.FinalData{
533					Status:     "cancelled",
534					Error:      ctx.Err().Error(),
535					DurationMS: time.Since(start).Milliseconds(),
536					RoutingActual: &harnesses.RoutingActual{
537						Harness:  decision.Harness,
538						Provider: decision.Provider,
539						Model:    decision.Model,
540					},
541				})
542				return
543			case <-timer.C:
544			}
545		}
546	
547		text, ok := meta["script.stdout"]
548		if !ok {
549			finalizeAndEmit(out, seq, meta, req, sl, harnesses.FinalData{
550				Status:     "failed",
551				Error:      "script harness requires metadata script.stdout",
552				DurationMS: time.Since(start).Milliseconds(),
553				RoutingActual: &harnesses.RoutingActual{
554					Harness:  decision.Harness,
555					Provider: decision.Provider,
556					Model:    decision.Model,
557				},
558			})
559			return
560		}
561		exitCode := metadataInt(meta, "script.exit_code")
562		final := harnesses.FinalData{
563			Status:     "success",
564			ExitCode:   exitCode,
565			FinalText:  text,
566			DurationMS: time.Since(start).Milliseconds(),
567			RoutingActual: &harnesses.RoutingActual{
568				Harness:  decision.Harness,
569				Provider: decision.Provider,
570				Model:    decision.Model,
571			},
572		}
573		if text != "" {
574			emitJSONRaw(out, seq, harnesses.EventTypeTextDelta, meta, harnesses.TextDeltaData{Text: text})
575		}
576		if exitCode != 0 {
577			final.Status = "failed"
578			final.Error = metaValue(meta, "script.stderr", fmt.Sprintf("script exited with status %d", exitCode))
579		}
580		finalizeAndEmit(out, seq, meta, req, sl, final)
581	}
