1374	func (p *timeoutProviderInline) Chat(ctx context.Context, messages []agentcore.Message, tools []agentcore.ToolDef, opts agentcore.Options) (agentcore.Response, error) {
1375		if p.requestTimeout <= 0 {
1376			return p.inner.Chat(ctx, messages, tools, opts)
1377		}
1378		cctx, cancel := context.WithTimeout(ctx, p.requestTimeout)
1379		defer cancel()
1380		resp, err := p.inner.Chat(cctx, messages, tools, opts)
1381		if err != nil && ctx.Err() == nil && cctx.Err() == context.DeadlineExceeded {
1382			return resp, fmt.Errorf("%w: wall-clock %s", errProviderRequestTimeout, p.requestTimeout)
1383		}
1384		return resp, err
1385	}
