103	// writeEvent persists a raw agent event to the session log. Used by the
104	// native loop callback to capture llm.request / llm.response / tool.call /
105	// compaction.* events so kept-sandbox bundles preserve a complete trace
106	// for benchmark reruns and post-mortem debugging. session.start and
107	// session.end are skipped because writeStart/writeEnd own those records and
108	// enrich them with service-side routing fields the loop does not see.
109	func (sl *serviceSessionLog) writeEvent(ev agentcore.Event) {
110		if sl == nil || sl.logger == nil {
111			return
112		}
113		switch ev.Type {
114		case agentcore.EventSessionStart, agentcore.EventSessionEnd,
115			agentcore.EventOverride, agentcore.EventRejectedOverride:
116			return
117		}
118		sl.logger.Write(ev)
119	}
