142	// close flushes the underlying file. Safe to call multiple times.
143	func (sl *serviceSessionLog) close() {
144		if sl == nil || sl.logger == nil {
145			return
146		}
147		sl.closeOnce.Do(func() {
148			_ = sl.logger.Close()
149		})
150	}
151	
152	// endWritten reports whether writeEnd has already recorded a terminal event.
153	func (sl *serviceSessionLog) endWritten() bool {
154		if sl == nil {
155			return false
156		}
157		return sl.endWrote.Load()
158	}
